1251			for idx := range weights {
1252				weights[idx] = 1
1253			}
1254		}
1255		out := make([]deliveredPromptCost, len(items))
1256		var allocatedBytes int64
1257		var allocatedTokens int64
1258		for idx, weight := range weights {
1259			if idx == len(items)-1 {
1260				out[idx] = deliveredPromptCost{
1261					PromptSizeBytes:       total.PromptSizeBytes - allocatedBytes,
1262					EstimatedPromptTokens: total.EstimatedPromptTokens - allocatedTokens,
1263				}
1264				break
1265			}
1266			promptBytes := total.PromptSizeBytes * weight / totalWeight
1267			promptTokens := total.EstimatedPromptTokens * weight / totalWeight
1268			out[idx] = deliveredPromptCost{
1269				PromptSizeBytes:       promptBytes,
1270				EstimatedPromptTokens: promptTokens,
1271			}
1272			allocatedBytes += promptBytes
1273			allocatedTokens += promptTokens
1274		}
